package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry.LF_NORMAL;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry.LF_OLDNORM;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TarArchiveEntry_isFile_TriageGen2Test {

    private static final byte LF_OTHER = 0x00; // Assuming a non-link flag value for testing

    @Test
    public void testIsFile_WithFileObjectTrue() {
        // Mocking behavior via File constructor if possible, 
        // but since we can't easily mock 'File' without PowerMock, 
        // we use the provided constructor that accepts a File.
        // Note: file.isFile() on a real file depends on the filesystem.
        // For a unit test, we aim to trigger the 'if (file != null)' branch.

        // Create a temporary file to ensure file.isFile() returns true
        try {
            File tempFile = File.createTempFile("testFile", ".tmp");
            tempFile.deleteOnExit();
            TarArchiveEntry entry = new TarArchiveEntry(tempFile);
            assertTrue(entry.isFile());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testIsFile_WithFileObjectFalse() {
        try {
            // Create a directory to ensure file.isFile() returns false
            File tempDir = new File(System.getProperty("java.io.tmpdir"), "testDir_" + System.currentTimeMillis());
            tempDir.mkdir();
            tempDir.deleteOnExit();

            TarArchiveEntry entry = new TarArchiveEntry(tempDir);
            assertFalse(entry.isFile());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testIsFile_WithLinkFlagOldNorm() {
        // Constructor: public TarArchiveEntry(final String name, final byte linkFlag, final boolean preserveLeadingSlashes);
        TarArchiveEntry entry = new TarArchiveEntry("testname", LF_OLDNORM, false);
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_WithLinkFlagNormal() {
        TarArchiveEntry entry = new TarArchiveEntry("testname", LF_NORMAL, false);
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_WithOtherLinkFlagAndNameNotEndingWithSlash() {
        // Covers: if (file == null) -> if (linkFlag != LF_OLDNORM && linkFlag != LF_NORMAL) -> return !getName().endsWith("/")
        TarArchiveEntry entry = new TarArchiveEntry("testname", LF_OTHER, false);
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_WithOtherLinkFlagAndNameEndingWithSlash() {
        // Covers: return !getName().endsWith("/") where name ends with /
        TarArchiveEntry entry = new TarArchiveEntry("testname/", LF_OTHER, false);
        assertFalse(entry.isFile());
    }
}
